public static int biggestSum(int[] arr) {
    int max = 0;
    int sum = 0;
    boolean started = false;   // כבר עברנו את ה-0 הראשון?
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] == 0) {
            // נגמר קטע בין שני אפסים (או שזה ה-0 הראשון — לפניו אין קטע)
            if (started && sum > max) {
                max = sum;
            }
            started = true;
            sum = 0;
        } else {
            sum = sum + arr[i];
        }
    }
    return max;
}

